I=[[4,0,7],[3,8,6],[5,1,2]]
O=[[4,0,7,5,3,4],[3,8,6,1,8,0],[5,1,2,2,6,7],[7,6,2,2,1,5],[0,8,1,6,8,3],[4,3,5,7,0,4]]
def rot(g,k):
    for _ in range(k):
        g=[list(r) for r in zip(*g[::-1])]
    return g
for k in range(4):
    R=rot(I,k)
    # check top-left offset positions
    for name,(orow,ocol) in [('TL',(0,0)),('TR',(0,3)),('BL',(3,0)),('BR',(3,3))]:
        block=[row[ocol:ocol+3] for row in O[orow:orow+3]]
        if block==R: print(k,name)
